@push('styles')<style>:root{--bg:#04131b;--line:rgba(110,220,240,.14);--text:#edfaff;--muted:#8caab7;--accent:#45c8e8}body{background:radial-gradient(circle at 80% -10%,rgba(54,188,220,.18),transparent 34%),linear-gradient(180deg,#031018,#061923 48%,#031018);color:var(--text)}.shell{width:min(1180px,calc(100% - 32px));margin:auto}.site-header{position:sticky;top:0;z-index:30;border-bottom:1px solid var(--line);background:rgba(3,16,24,.82);backdrop-filter:blur(20px)}.nav{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:15px}.brand{display:flex;align-items:center;gap:10px;font-weight:800;min-width:0}.brand img{width:38px;height:38px;object-fit:contain;border-radius:10px}.brand span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:270px}.menu{display:flex;align-items:center;gap:5px}.menu a{padding:9px 10px;border-radius:10px;color:var(--muted);font-size:11px;white-space:nowrap}.menu a:hover{color:var(--text);background:rgba(69,200,232,.08)}.menu a i{margin-right:5px}.menu-btn{display:none;width:40px;height:40px;border:1px solid var(--line);border-radius:11px;background:rgba(255,255,255,.035);color:var(--text);font-size:18px}.hero{padding:82px 0 55px;display:grid;grid-template-columns:1.25fr .75fr;gap:42px;align-items:center}.eyebrow{font-size:10px;letter-spacing:.2em;color:var(--accent);text-transform:uppercase}.hero h1{font-size:clamp(42px,7vw,78px);line-height:.96;margin:12px 0 20px;letter-spacing:-.045em}.hero p{max-width:680px;color:var(--muted);font-size:17px;line-height:1.75}.actions{display:flex;gap:10px;margin-top:28px}.btn{display:inline-flex;align-items:center;gap:9px;padding:12px 16px;border-radius:12px;background:linear-gradient(135deg,#39bddd,#24a6cb);font-weight:750;font-size:13px}.btn.secondary{background:rgba(255,255,255,.035);border:1px solid var(--line);color:#b9d2db}.energy-stage{min-height:330px;border:1px solid var(--line);border-radius:30px;background:radial-gradient(circle at 50% 40%,rgba(69,200,232,.18),transparent 38%),linear-gradient(145deg,rgba(10,45,59,.9),rgba(5,24,33,.8));display:grid;place-items:center;position:relative;overflow:hidden}.energy-stage:before,.energy-stage:after{content:"";position:absolute;border:1px solid rgba(69,200,232,.16);border-radius:50%;animation:orbit 8s linear infinite}.energy-stage:before{width:220px;height:220px}.energy-stage:after{width:310px;height:310px;animation-duration:13s;animation-direction:reverse}.energy-core{width:105px;height:105px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,#d9fbff 0 5%,#45c8e8 22%,rgba(69,200,232,.08) 62%,transparent 70%);box-shadow:0 0 55px rgba(69,200,232,.38);animation:core 3s ease-in-out infinite}.energy-core i{font-size:42px;color:#e9fdff;filter:drop-shadow(0 0 14px rgba(69,200,232,.8))}@keyframes core{50%{transform:scale(1.08);box-shadow:0 0 85px rgba(69,200,232,.55)}}@keyframes orbit{to{transform:rotate(360deg)}}section{padding:55px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:20px}.section-head h2{font-size:28px;margin:6px 0}.section-head p{color:var(--muted);max-width:600px;line-height:1.6}.stats,.plant-grid,.content-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.stat,.plant,.content-card{border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(9,39,52,.86),rgba(5,24,33,.82))}.stat{padding:21px}.stat small{display:block;color:#789aa8;text-transform:uppercase;font-size:10px}.stat strong{display:block;font-size:30px;margin-top:10px}.plant,.content-card{padding:20px;min-height:170px}.plant-top{display:flex;justify-content:space-between;gap:10px}.plant h3,.content-card h3{margin:8px 0;font-size:18px}.pill{padding:5px 8px;border-radius:999px;font-size:9px;background:rgba(32,212,170,.1);color:#6ee8c9;height:max-content}.plant p,.content-card p{color:var(--muted);font-size:12px;line-height:1.6}.meta{display:flex;gap:8px;flex-wrap:wrap;color:#9cc0cb;font-size:10px}.content-card .type{color:var(--accent);font-size:9px;text-transform:uppercase}.content-card time{display:block;color:#678895;font-size:9px;margin-top:12px}.empty{padding:28px;border:1px dashed var(--line);border-radius:16px;color:var(--muted)}footer{border-top:1px solid var(--line);padding:35px 0 60px;color:#6f929f;font-size:11px}@media(max-width:780px){.menu-btn{display:grid;place-items:center}.menu{display:none;position:absolute;top:68px;right:12px;left:12px;padding:10px;flex-direction:column;align-items:stretch;background:rgba(4,19,27,.97);border:1px solid var(--line);border-radius:15px;box-shadow:0 20px 50px rgba(0,0,0,.35)}.menu.open{display:flex}.menu a{padding:12px}.hero{grid-template-columns:1fr;padding-top:55px}.energy-stage{min-height:230px}.stats,.plant-grid,.content-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.shell{width:calc(100% - 24px)}.brand span{max-width:180px;font-size:13px}.hero h1{font-size:42px}.hero p{font-size:14px}.energy-stage{min-height:190px}.energy-core{width:82px;height:82px}.energy-core i{font-size:32px}.stats,.plant-grid,.content-grid{grid-template-columns:1fr}section{padding:40px 0}}</style>@endpush
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.menu-btn'),m=document.querySelector('#site-menu');if(!b||!m)return;b.addEventListener('click',()=>{const open=m.classList.toggle('open');b.setAttribute('aria-expanded',open);b.innerHTML=open?'<i class="fa-solid fa-xmark"></i>':'<i class="fa-solid fa-ellipsis"></i>'});m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded','false');b.innerHTML='<i class="fa-solid fa-ellipsis"></i>'}))});</script>@endpush